Generated Query:
PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber (COUNT(DISTINCT ?claim) AS ?claimCount)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?coverage .
    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber (SUM(?premiumValue) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?policyCoverageDetail a in:PolicyCoverageDetail ;
                          in:hasPolicy ?policy ;
                          in:hasPremiumAmount ?premium .

    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumValue .
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber
       (SUM(?lossPaymentVal + ?lossReserveVal) AS ?totalLossAmount)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentVal .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveVal .
    }

    BIND(COALESCE(xsd:decimal(?lossPaymentVal), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lossReserveVal), 0) AS ?lossReserveVal)
  }
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policyHolder ?policyHolderId ?policy ?policyNumber ?coverageDetail ?premium ?premiumAmount ?premiumAmountMonthly ?premiumPeriod
WHERE {
  SERVICE <mapped> {
    ?coverageDetail a in:PolicyCoverageDetail ;
                    in:hasPolicy ?policy ;
                    in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder .
    ?premium a in:Premium .

    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }
    OPTIONAL { ?policy in:policyNumber ?policyNumber . }
    OPTIONAL { ?premium in:premiumAmount ?premiumAmount . }
    OPTIONAL { ?premium in:premiumAmountMonthly ?premiumAmountMonthly . }
    OPTIONAL { ?premium in:premiumPeriod ?premiumPeriod . }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}
